import type { StoragePort } from "../../src/storage/port";
import { buildTabbedLayout } from "../../src/ui/tabs";
import { createNotebookStore, type NotebookStore } from "../notebook/store";
import { composePrefillKey, type Mode } from "./model";
import { createComposeStore, type ComposeStore } from "./store";
import { mountPractice } from "./practice";
import { mountLists } from "./lists";

