export type ComposeLabels = typeof DEFAULT_COMPOSE_LABELS;

export interface ComposeProps {
  storage: StoragePort;
  aiClient: AiClient | null;
  subjectKey?: string;
  tasks: { system: string; model?: string; effort?: AiEffort };
  grader: { system: string; model?: string; effort?: AiEffort };
  categories?: string[];
  levels?: { key: string; label: string }[];
  modes?: Mode[];
  labels?: Partial<ComposeLabels>;
  outline?: { doc: string };
  stopwords?: string[];
  speechLang?: string;
  batch?: number;
  srs?: { intervalsDays?: Record<number, number> };
}

type Tab = "practice" | "revise" | "history";

export interface ComposeCtx {
  store: ComposeStore;
  terms: NotebookStore;
  ai: AiClient | null;
  props: ComposeProps;
  L: ComposeLabels;
  now: () => number;
  openTask: (id: string) => void;
  generateFocus: (categories: string[]) => void;
  refreshCounts: () => void;
  remember: (key: string, value: string | null) => void;
  recall: (key: string) => string | null;
}

export function mountCompose(container: HTMLElement, props: ComposeProps): void {
  const L: ComposeLabels = { ...DEFAULT_COMPOSE_LABELS, ...(props.labels ?? {}), modes: { ...DEFAULT_COMPOSE_LABELS.modes, ...(props.labels?.modes ?? {}) } };
  const ns = props.subjectKey ?? "compose";
  const lsKey = (k: string) => `lh:${ns}:compose:${k}`;
  const store = createComposeStore(props.storage);
  const terms = createNotebookStore(props.storage, new Set((props.stopwords ?? []).map((w) => w.toLowerCase())));

  const layout = buildTabbedLayout(container, "lh-nb lh-cm", [
    { id: "practice", label: L.tabPractice },
    { id: "revise", label: L.tabRevise },
    { id: "history", label: L.tabHistory },
  ], L.offline, (id) => go(id as Tab));

  const ctx: ComposeCtx = {
    store, terms, ai: props.aiClient, props, L,
    now: () => Date.now(),
    openTask: (id) => { go("practice"); void practice.openTask(id); },
    generateFocus: (cats) => { go("practice"); practice.generateFocus(cats); },
    refreshCounts: () => void refreshCounts(),
    remember: (k, v) => { try { if (v === null) localStorage.removeItem(lsKey(k)); else localStorage.setItem(lsKey(k), v); } catch { /* private mode */ } },
    recall: (k) => { try { return localStorage.getItem(lsKey(k)); } catch { return null; } },
  };

  const practice = mountPractice(layout.panes.get("practice")!, ctx);
  const revise = mountLists(layout.panes.get("revise")!, ctx, "revise");
  const history = mountLists(layout.panes.get("history")!, ctx, "history");

  function go(tab: Tab): void {
    if (!layout.show(tab)) return;
    ctx.remember("tab", tab);
    if (tab === "revise") void revise.refresh();
    else if (tab === "history") void history.refresh();
  }

  async function refreshCounts(): Promise<void> {
    const all = await store.list();
    const now = ctx.now();
    const due = all.filter((t) => t.summary.queued && t.summary.due_at <= now).length;
    layout.setCount("revise", due ? String(due) : "");
    layout.setFlag("revise", "lh-nb-tab--due", due > 0);
    layout.setCount("history", all.length ? String(all.length) : "");
    layout.banner.hidden = store.online;
  }

  void refreshCounts();
  let handed: { words?: string[] } | null = null;
  try {
    const raw = localStorage.getItem(composePrefillKey(ns));
    localStorage.removeItem(composePrefillKey(ns));
    handed = raw ? (JSON.parse(raw) as { words?: string[] }) : null;
  } catch { /* private mode or bad value */ }
  if (handed?.words?.length) { go("practice"); practice.useWords(handed.words); }
  else {
    const saved = ctx.recall("tab") as Tab | null;
    go(saved === "revise" || saved === "history" ? saved : "practice");
  }
}
